window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-foreign|wj-08|知识点四|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 6, "q": "为确保统一后的德国基础教育发展能适应本国经济、社会发展的要求，德国政府除开展基础教育体制与结构改革外，还要求培养（　）", "opts": ["创造能力、外语能力、信息能力", "创造能力、科学能力、信息能力", "科学能力、外语能力、信息能力", "创造能力、外语能力、科学能力"], "a": 0, "exp": "此题考查德国统一以来的教育改革。统一后的德国注重学生外语能力、创造能力以及现代信息技术应用能力的培养。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 7, "q": "德国20世纪下半叶的《总纲计划》《汉堡协定》和“德国统一以来的教育改革”之间的内在联系是（　）", "opts": ["对教育内容的继承与改革", "对教育方法的继承与改革", "对学制体系的继承与改革", "对课程体系的继承与改革"], "a": 2, "exp": "此题考查德国20世纪下半叶的教育改革。方法和课程体系的改革。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 8, "q": "下列关于德国的职业教育特色，说法正确的一项是（　）", "opts": ["采用双元制，即学生必须经过职业学校和企业的双向培训", "《阿斯蒂埃法》将职业教育变为国家事业", "《史密斯一休斯法案》形成了从中央到地方的职业教育系统", "建立城市技术学院，扩大职业教育的规模"], "a": 0, "exp": "此题考查德国职业教育。A.德国的职业教育采用双元制，职业学校学生必须经过职业学校和企业两个场所的培训。√B.修改：《阿斯蒂埃法》是法国的职业教育法案，有“技术教育宪章”之称。C.修改：《史密斯一休斯法案》是美国的职业教育法案，将职业教育的发展变为政府行为。D.修改：英国在《1988年教育改革法》中，建立城市技术学院，扩大职业教育的规模。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-08|知识点四|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-08", "chName": "第八章 德国的近现代教育制度", "sec": "知识点四：20世纪下半叶的德国现代教育制度", "no": 9, "q": "1990年之后，下列事项在德国不可能出现的是（　）", "opts": ["学生不经过考试直接升人主要学校", "学生接受了十年义务教育", "学生接受了三年制义务职业教育", "学生经师资养成所培训，成为完全中学的老师"], "a": 3, "exp": "此题考查德国统一以来的教育改革。A.基础学校的毕业生，多数不经过考试直接升人主要学校或综合学校，部分学生需经过考试分别进人其他中学。B.德国各州实行九年义务教育，仅勃兰登堡实行十年义务教育。C.德国统一后，各州在义务教育之后实施三年制义务职业教育。D.德国统一后，师资培养任务已由高等学校承担，不需要师资养成所培训。此题为选非题。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 65}},
  {"id": "kc|edu-foreign|wj-09|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点一：17一18世纪的俄国近代教育概况", "no": 1, "q": "17世纪后半叶，俄国实行新的文化教育发展政策，开设普通和专门学校，提出创建科学院的设想，使教育得到很大进步，这是（（　）的成果。（　）", "opts": ["叶卡捷琳娜二世改革", "亚历山大一世改革", "罗蒙诺索夫改革", "彼得一世改革"], "a": 3, "exp": "此题考查彼得一世的教育改革。A.18世纪后半叶，叶卡捷琳娜二世设立“国民学校委员会”，并颁布了《俄罗斯帝国国民学校章程》。B.19世纪初，亚历山大一世颁布《国民教育暂行条例》，实施《大学附属学校章程》，借鉴法国大学区制逐步建立和完善了学校体系和管理体制。C.18世纪中期，罗蒙诺索夫倡导设立莫斯科大学。D.17世纪后半叶，彼得一世在国内进行了教育改革，主要内容是实行新的文化教育发展政策，其中包括简化俄文字母，翻译国外书籍等；开设普通学校，传授读、写、算等初级知识，强制贵族子弟学习文化；设立专门学校，培养国家人才；提出创建科学院的设想。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点一：17一18世纪的俄国近代教育概况", "no": 2, "q": "18世纪中期，俄国建立了莫斯科大学，实行世俗化和民主化的原则，不设立神学系。该大学的创立者是（　）", "opts": ["彼得一世", "叶卡捷琳娜二世", "亚历山大二世", "罗蒙诺索夫"], "a": 3, "exp": "此题考查莫斯科大学。莫斯科大学是在俄国科学家罗蒙诺索夫的倡导下设立的，具有世俗性和民主化的特点。这所大学打破传统的惯例，只设法律、哲学、医学三个系和两个文科中学，不设神学系。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点一：17一18世纪的俄国近代教育概况", "no": 3, "q": "俄国历史上第一部关于国民教育制度的法令是1786年颁布的（　）", "opts": ["《大学附属学校章程》", "《国民教育暂行条例》", "《俄罗斯帝国国民学校章程》", "《俄罗斯帝国大学章程》"], "a": 2, "exp": "此题考查《俄罗斯帝国国民学校章程》。A/B.19世纪初，亚历山大一世颁布《国民教育暂行条例》，实施《大学附属学校章程》，借鉴法国大学区制逐步建立并完善了学校体系和管理体制。C.18世纪后半叶，叶卡捷琳娜二世颁布了《俄罗斯帝国国民学校章程》，这是俄国历史上最早颁布的关于国民教育制度的法令，奠定了近代俄国国民教育的基础。√D.亚历山大二世于1863年颁布《俄罗斯帝国大学章程》，给予大学一些学术自由和自治权。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点二：19世纪的俄国近代教育概况", "no": 1, "q": "19世纪，俄国历史上第一次规定建立女子学校的章程是（　）", "opts": ["《俄罗斯帝国大学章程》", "《国民教育部女子学校章程》", "《女子学校令》", "《俄罗斯帝国国民学校章程》"], "a": 1, "exp": "此题考查《国民教育部女子学校章程》。A.《俄罗斯帝国大学章程》规定给予大学一些学术自由和自治权。B.19世纪60年代颁布的《国民教育部女子学校章程》是俄国历史上第一次规定建立女子学校的章程，推动了女子教育的发展。√C.无此法案。D.《俄罗斯帝国国民学校章程》是俄国历史上最早颁布的关于国民教育制度的法令。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 1, "q": "下列选项中，不属于苏联建国初期（1917一1920年）教育改革主要措施的是（　）", "opts": ["成立了国家教育委员会，作为全国教育的领导机构", "《统一劳动学校规程》体现了非宗教的、民主的、社会主义的教育原则", "规定各种教科书必须由教育人民委员部审查、批准", "建立了一支新的无产阶级教师队伍"], "a": 2, "exp": "此题考查苏联20世纪10一20年代的教育改革。C选项是在《关于小学和中学的决定》中提出的，其还提出采用长期稳定的教科书，停止发行“工作手册”“活页课本”，属于20世纪30年代的调整、巩固与发展的措施。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 2, "q": "苏联提出“建立九年制的统一劳动学校”的文件是（　）", "opts": ["1917年《史密斯—休斯法案》", "1918年《统一劳动学校规程》", "1931年《关于小学和中学的决定》", "1977年《关于进一步完善普通学校学生的教学、教育和劳动训练的决议》"], "a": 1, "exp": "此题考查《统一劳动学校规程》。A.《史密斯一休斯法案》是美国的法案，核心是强化中等职业教育，和苏联的教育改革无关。B.1918年，苏俄制定《统一劳动学校规程》和《统一劳动学校宣言》，建立新的学校教育制度一一统一劳动学校。√C.《关于小学和中学的决定》的核心是强化教学内容的系统性，并非创设九年制统一劳动学校。D.《关于进一步完善普通学校学生的教学、教育和劳动训练的决议》是苏联后期优化普通教育与劳动训练结合的文件，时间和内容均与题干不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 3, "q": "下列关于《统一劳动学校规程》的说法错误的是（　）", "opts": ["学校类型分为高、低两级，具有等级性", "统一劳动学校均具有免费性", "所有学生都要参加体力劳动", "贯彻了非宗教的、社会主义的教育原则"], "a": 0, "exp": "此题考查《统一劳动学校规程》。“统一”原则表现为学校类型是统一的，高、低两级是相互衔接的，没有等级性。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 66}},
  {"id": "kc|edu-foreign|wj-09|知识点三|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 4, "q": "20世纪20年代苏联“综合教学大纲”的突出特点是（　）", "opts": ["取消学科界限，并以劳动为中心", "体现知识的综合性和全面性", "体现教学方法的综合性和多样性", "体现教学组织形式的多样性"], "a": 0, "exp": "此题考查“综合教学大纲”。20世纪20年代苏联的教育以劳动为中心，忽视知识的学习，B、C、D选项不符合题意。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点三|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 5, "q": "1931年苏联通过的《关于小学和中学的决定》成为国民教育的纲领性文件，其直接指向之前的改革端，即（　）", "opts": ["重视劳动教育，轻视知识教育", "重视劳动教育，轻视综合训练", "重视劳动教育，轻视成绩考核", "重视劳动教育，轻视个性发展"], "a": 0, "exp": "此题考查《关于小学和中学的决定》。20世纪20年代苏联教育的中心是劳动，忽视知识的学习，所以20世纪30年代的《关于小学和中学的决定》直接指向20世纪20年代的改革端：重视劳动教育，轻视知识教育。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点三|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 6, "q": "第二次世界大战结束以前，苏联在实施教育与生产劳动相结合的过程中，曾出现“把智育视为教育的中心任务”“片面追求升学率”“相对忽视劳动教育”的现象。此现象发生于（　）", "opts": ["建国初期的教育改革", "20世纪20年代的教育改革", "20世纪30年代的教育改革", "20世纪80年代的教育改革"], "a": 2, "exp": "此题考查苏联20世纪30年代的教育改革。20世纪苏联教育的发展是曲折而反复的：20年代（建国时期）重视劳动教育；30年代重视知识教育；50年代重视劳动教育；60年代重视知识教育；70年代重视劳动教育；80年代开始将知识和劳动教育综合起来。对应题干的“二战”前和忽视劳动教育，可知答案为30年代。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点三|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点三：20世纪上半叶的苏联现代教育制度", "no": 7, "q": "苏联某法案要求新的教学大纲要保证学生“能真正巩固而有系统地获得各门学科的基本知识、技能和技巧”，并要求采用长期稳定的教科书，取消“分组实验室制”。该法案可能颁布于（　）", "opts": ["1925年", "1931年", "1958年", "1977年"], "a": 1, "exp": "此题考查苏联教育政策的钟摆现象。20世纪苏联教育发展的特点：钟摆现象一—“劳知劳知劳融合”。题干中提及的法案内容偏重知识，而苏联的教育只有在20世纪30年代和20世纪60年代是偏重知识的。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点四：20世纪下半叶的苏联现代教育制度", "no": 1, "q": "苏联在20世纪50年代再次开启重视劳动教育的新一轮教育改革，这次改革最根本的特点是（　）", "opts": ["加强教育与生活的联系，侧重劳动教育", "拉长义务教育年限", "重视职业教育", "发展高等教育"], "a": 0, "exp": "此题考查苏联20世纪50年代的教育改革。A、B、C、D四个选项均为苏联20世纪50年代教育改革的特点，但A选项是最根本的特点。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点四：20世纪下半叶的苏联现代教育制度", "no": 2, "q": "20世纪50年代，为了解决升学和就业之间的矛盾，苏联颁布了《关于加强学校同生活的联系和进一步发展全国国民教育制度的建议》。关于此文件，下列说法错误的是（：（　）", "opts": ["主要针对普通教育、职业教育、高等教育开展改革1958年的教育改革（《关于加强学校同生活的联系和进一步发展全国国民教育制度的建议》）", "优点是重知识教学，提高了教育质量1966年的教育改革（《关于进一步改进普通中学工作的措施》）", "重视职业教育，为学生就业提供机会1977年的教育改革（《关于进一步完善普通学校学生的教学、教育和劳动训练的决议》）", "义务教育年限延长1984年的教育改革（《普通学校和职业学校改革的基本方针》）"], "a": 1, "exp": "此题考查《关于加强学校同生活的联系和进一步发展全国国民教育制度的建议》。1958年颁布的《关于加强学校同生活的联系和进一步发展全国国民教育制度的建议》的重点在于加强学校和生活的联系，为学生就业做准备，但顾此失彼，生产劳动教学占据较多时间，削弱了知识的传授，导致了教学质量的下降。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点四|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点四：20世纪下半叶的苏联现代教育制度", "no": 3, "q": "苏联形成了四五二学制的时期是（　）", "opts": ["20世纪50年代", "20世纪60年代", "20世纪70年代", "20世纪80年代"], "a": 3, "exp": "此题考查苏联20世纪80年代的教育改革。1984年，苏联通过了《普通学校和职业学校改革的基本方针》，该法案形成了四五二学制，“四”指小学四年，“五”指不完全中学五年，“二”指中等学校两年。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点四|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点四：20世纪下半叶的苏联现代教育制度", "no": 4, "q": "苏联20世纪20一90年代以来教育改革最为宏观的特点是（　）", "opts": ["重视劳动教育", "重视知识教育", "钟摆现象", "重视劳动与知识相结合"], "a": 2, "exp": "此题考查苏联20世纪20一90年代教育改革的特点。苏联的教育改革重心从20世纪20年代以来不断摇摆：20年代以劳动为重心，30年代以知识为重心，40年代处于战争时期，50年代以劳动为重心，60年代以知识为重心，70年代以劳动为重心，80年代开始将知识和劳动综合起来。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点四|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点四：20世纪下半叶的苏联现代教育制度", "no": 5, "q": "思想后再做此题。关于20世纪苏联教育的钟摆现象，下列说法不正确的一项是（　）", "opts": ["20世纪20年代：偏向劳动教育", "20世纪30年代：偏向知识教育", "20世纪50年代：偏向劳动教育", "20世纪70年代：偏向知识教育"], "a": 3, "exp": "此题考查苏联各个时期教育改革的特点。苏联的教育改革重心从20世纪20年代以来不断摇摆：20年代以劳动为重心，30年代以知识为重心，40年代处于战争时期，50年代以劳动为重心，60年代以知识为重心，70年代以劳动为重心，80年代开始将知识和劳动综合起来。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 67}},
  {"id": "kc|edu-foreign|wj-09|知识点四|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-09", "chName": "第九章 俄国（苏联）的近现代教育制度", "sec": "知识点四：20世纪下半叶的苏联现代教育制度", "no": 6, "q": "当今俄罗斯的教育管理体制是（　）", "opts": ["中央集权制", "中央地方合作制", "州教育领导制", "联邦中央、联邦主体、地方三级教育管理体制"], "a": 3, "exp": "此题考查俄罗斯的教育管理体制。20世纪90年代，俄罗斯形成联邦中央、联邦主体、地方三级教育管理体制。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点一：17一18世纪的美国近代教育概况", "no": 1, "q": "美国最先采取义务教育措施的州是（　）", "opts": ["北部殖民地兴办义务教育A弗吉尼亚州下列关于17—18世纪的美国教育说法正确的一项是（", "马萨诸塞州南部殖民者热衷兴办中等教育", "威斯康星州中部殖民地主要是文实中学）", "康涅狄格州17世纪整个美洲还没有一所高等教育院校"], "a": 1, "exp": "此题考查美国义务教育概况。1852年，马萨诸塞州第一个颁布强迫义务教育法，规定8～12岁适龄儿童每年须人学学习12周。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点一：17一18世纪的美国近代教育概况", "no": 2, "q": "18世纪，在镇周围的乡村设若干教学点，各教学点附近的儿童定时集中，由市镇学校的教师去各教学点上课，这便是“学区制”的萌芽。该类学校指（　）", "opts": ["文实学校", "巡回学校", "文科学校", "完全学校"], "a": 1, "exp": "此题考查18世纪美国的教育。A.文实学校：18世纪美国出现的中等教育机构。B.巡回学校：1725年，马萨诸塞州出现了巡回学校，即在镇周围的乡村设若干教学点，各教学点附近的儿童定时集中，由市镇学校的教师去各教学点巡回上课。后来，各教学点所在区域采取独立办学的做法，这便是“学区制”的萌芽。√C.文科学校：通常指注重古典语言、文学、历史等人文科目的学校，在欧洲历史悠久。D.完全学校：在不同国家或历史背景下有不同含义，有时指包含小学与中学一贯制的学校，有时是特定类型中学的名称，如德国“完全中学”。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点一：17一18世纪的美国近代教育概况", "no": 3, "q": "富兰克林于1751年在费城创办了一所学校，这是美国中等教育界的新生事物，是美国中等教育的发展进人新阶段的标志。该学校是（　）", "opts": ["文实中学", "文法中学", "公立中学", "拉丁文法中学"], "a": 0, "exp": "此题考查18世纪美国的中等教育。A.文实中学：富兰克林于1751年在费城创办了一所文实中学，这是美国中等教育界的新生事物，是美国中等教育的发展进人新阶段的标志。√B.文法中学：英国传统中等教育机构，以教授古典语言文法和古典文学为主。C.公立中学：美国公立中学的出现与发展进一步强化了公立教育运动在中等教育领域内的延伸，它注重切合社会实际需要，重视英语、数学、自然科学与现代语言的教学。D.拉丁文法中学：北美殖民地时期主要的中等教育形式，以拉丁语学习为核心，课程单一。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点一|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点一：17一18世纪的美国近代教育概况", "no": 4, "q": "）关于实行普及免费的初等教育和建立单轨制免费公立学校系统的理想，成为19世纪公立学校运动的先声。（　）", "opts": ["富兰克林", "贺拉斯·曼", "杰斐逊", "巴纳德"], "a": 2, "exp": "此题考查公立学校运动。A.富兰克林于1751年在费城创办了第一所文实中学，这是美国中等教育的发展进人新阶段的标志。B.贺拉斯·曼倡导开展了公立学校运动，被誉为“美国公立学校之父”。C.杰斐逊的《知识普及法案》是18世纪美国建国后倡导普及教育和公共教育制度的典型，成为19世纪公立学校运动的先声。√D.巴纳德是美国康涅狄格州建立免费公共学校议案的发起人和主要倡导者。此套课程公众号【研大]", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 1, "q": "美国的教育领导体制是典型的（　）", "opts": ["中央集权制", "地方分权制", "中央地方共权制", "民族区域自治制"], "a": 1, "exp": "此题考查美国的教育领导体制。美国的教育领导体制是典型的地方分权制，教育的管理权主要在州一级政府。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 2, "q": "公立学校运动的本质特征是（　）", "opts": ["由公众团体集资兴办的，培养一般公职人员且在公开场所办学的教育", "由公共税收维持、公共教育机关管理，面向所有公众的教育", "由公共税收维持、公共教育机关管理，面向所有中产阶级子弟的义务教育", "由公共教育机关管理的、在公共场所办学的、由公众集资兴办的义务教育"], "a": 1, "exp": "此题考查公立学校运动。A.该项为英国公学的特征。B.公立学校运动的本质特征是由公共税收维持、公共教育机关管理、面向所有公众的教育。√C.公立学校运动是面向所有公众的教育，而不是面向所有中产阶级子弟的教育。D.该项杂了英国公学和公立学校运动的特征。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 68}},
  {"id": "kc|edu-foreign|wj-10|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 3, "q": "美国公立学校运动和英国公学最大的区别在于（　）", "opts": ["是否有经费支持", "是否有管理机构", "是否由国家管理", "是否免费"], "a": 2, "exp": "此题考查美国公立学校运动和英国公学。美国公立学校运动主要是指依靠公共税收维持，由公共教育机关管理，面向所有公众的免费的义务教育运动。英国公学是由公众团体集资兴办，培养一般公职人员，其学生在公开场所接受教育的中等私立学校，是典型的贵族学校。二者最大的区别在于是公立学校还是私立学校，是否由国家管理。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点二|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 4, "q": "19世纪，美国从本国实际出发所独创的改变了高等教育重理论轻实际传统的教育机构是（　）", "opts": ["初级学院", "城市学院", "技术学院", "赠地学院"], "a": 3, "exp": "此题考查赠地学院。赠地学院是美国从本国实际出发所独创的高等教育机构，改变了高等教育重理论轻实际的传统，开创了高等教育为工农业生产服务的方向。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点二|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 5, "q": "美国第一部职业教育法是（　）", "opts": ["《莫雷尔法案》", "《史密斯一休斯法案》", "《阿斯蒂埃法》", "《国防教育法》"], "a": 0, "exp": "此题考查《莫雷尔法案》。A.1862年颁布的《莫雷尔法案》是美国第一部职业教育法，开创了在高等教育中开设职业教育的先例。√B.1917年美国的《史密斯一休斯法案》主张联邦政府应与州合作，提供工业、农业、商业和家政等方面科目的师资培训，同时对职业教育师资训练机构提供资助。C.《阿斯蒂埃法》是法国有关职业技术教育的法案，有法国“技术教育宪章”之称。D.1958年美国的《国防教育法》注重教育质量的提升。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点二|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 6, "q": "19世纪后半叶，美国研究型大学发展所借鉴的办学模式主要源于（　）", "opts": ["日本大学", "英国大学", "德国大学", "法国大学"], "a": 2, "exp": "此题考查19世纪美国的高等教育。19世纪初，德国洪堡领导创办的柏林大学是世界现代高等教育建立的标志，是世界各国现代教育的典范。19世纪后半叶，美国吸取德国经验，建立研究型大学。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点二|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点二：19世纪的美国近代教育概况", "no": 7, "q": "以下选项中，不属于19世纪的美国在工业革命推动下的教育发展特色的是（　）", "opts": ["形成双轨制教育体系，维护不同阶级的利益", "开展公立教育运动，颁布义务教育法，实行强迫人学", "颁布《莫雷尔法案》，主张高等教育为工农业生产服务", "女子被允许进人高等院校，出现了女子学院"], "a": 0, "exp": "此题考查19世纪美国教育的发展。双轨制是为了维护贵族和平民的不同利益而形成的，主要存在于英国等一些欧洲国家。美国教育没有形成典型的双轨制教育体系。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点三：20世纪上半叶的美国现代教育制度", "no": 1, "q": "《中等教育的基本原则》强调美国教育的指导原则是（：（　）", "opts": ["实用主义原则", "精英主义原则", "民主原则", "科学主义原则"], "a": 2, "exp": "此题考查《中等教育的基本原则》。《中等教育的基本原则》指出，美国教育的指导原则是民主原则。因此，答案选C。（说明：往年真题考过该报告的综合中学、服务社会发展的基本要点，考生还需要关注民主原则，以及七项目标一道德品格、公民资格、掌握基本的方法、职业、健康、适宜地使用闲暇、高尚的家庭成员。其中主要目标是公民资格、职业和高尚的家庭成员。）", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点三：20世纪上半叶的美国现代教育制度", "no": 2, "q": "20世纪30年代，美国进行的“八年研究”的主要目的是（　）", "opts": ["研究大学与中学的关系，解决升学与就业的矛盾", "研究中等学校课程改革的问题", "研究双轨制带来的负面影响", "探索发展职业教育的途径"], "a": 0, "exp": "”记忆题此题考查《中等教育的基本原则》。A.《中等教育的基本原则》肯定了美国的“六三三学制”和综合中学的地位。√B.《中小学教育法》重申了黑人和白人合校教育的政策。C.《教育改革法》是法国1959年颁布的，该法案推动了“市立初级中学”这种新型中等学校的问世。D.《美国2000年教育战略》明确指出未来美国教育改革的基本目标。】A.1971年，美国教育总署署长马兰为了提升学生的就业能力，倡导生计教育。旨在对进步主义学校的毕业生和传统学校的毕业生在大学的学习情况做对比研究。√C.美国20世纪60年代的课程改革是结构主义课程改革。D.20世纪70年代，由于公众对公立学校的教育质量普遍不满，美国掀起了“返回基础”教育运动。该运动实际是美国的一种恢复传统教育的思潮。】20世纪30年代，美国高等教育的发展带来了升学和就业的矛盾。为此，美国进步教育协会成立了大学与中学关系委员会，研究大学与中学的关系问题，开展了“八年研究”。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点三：20世纪上半叶的美国现代教育制度", "no": 3, "q": "初级学院运动实质上是对美国（）阶段教育改革的设想。（　）", "opts": ["初等教育", "中等教育", "职业教育", "高等教育"], "a": 3, "exp": "此题考查美国的初级学院运动。19世纪后半期，美国高等教育的教育目的和自身结构方面的问题引起广泛关注，芝加哥大学校长率先提出把大学的四个学年分为两个阶段：第一阶段的两年为“初级学院”；第二阶段的两年为“高级学院”。同时将课程分为两个部分。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点三|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点三：20世纪上半叶的美国现代教育制度", "no": 4, "q": "19世纪末20世纪初，美国兴起了一场推动中等教育向高等教育过渡的运动，其课程设置兼顾普通教育与职业教育知识。作为高等教育大众化、民主化进程的产物，该运动有力推动了高等教育的普及与发展。这场运动是（　）", "opts": ["公立教育运动", "劳作学校运动", "初级学院运动", "生计教育运动"], "a": 2, "exp": "此题考查美国的初级学院运动。A.公立教育运动：19世纪上半叶美国兴起的教育运动，旨在建立由公共税收维持、免费且普及的公立学校体系，重点在基础教育阶段，与中等教育向高等教育的过渡无关。B.劳作学校运动：20世纪初起源于德国的教育改革运动，强调通过劳动培养学生的实践能力和社会责任感，与美国的高等教育的发展无关。C.初级学院运动：19世纪末20世纪初美国兴起的教育运动，通过设立两年制的初级学院，衔接中等教育与高等教育，以低学费、办学灵活和职业教育为导向推动高等教育大众化，符合题干描述。√D.生计教育运动：20世纪70年代美国提出的教育改革，旨在将职业教育与普通教育结合，面向全体学生提供生计准备，提升其就业能力，并未体现高等教育的普及，且时间与题干不符。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 69}},
  {"id": "kc|edu-foreign|wj-10|知识点三|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点三：20世纪上半叶的美国现代教育制度", "no": 5, "q": "为了更好地推动职业教育的发展，美国在20世纪初主张联邦政府与州合作，提供各种职业教育师资培训的法案是（　）", "opts": ["《史密斯一休斯法案》", "全国职业教育促进会", "《阿斯蒂埃法》", "《巴尔福教育法》"], "a": 0, "exp": "此题考查《史密斯一休斯法案》。A.美国《史密斯一休斯法案》主张联邦政府应与州合作，提供工业、农业、商业和家政等方面科目的师资培训，同时对职业教育师资训练机构提供资助。√B.1906年，美国成立全国职业教育促进会，旨在推动制定一部能对全国职业教育提供财政补助的法律。C.1919年，法国通过有关职业技术教育的《阿斯蒂埃法》，该法有法国“技术教育宪章”之称。D.1902年，英国通过《巴尔福教育法》，对教育行政管理体制及初等教育和中等教育衔接问题进行了讨论，推动了英国公立中等教育的发展。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 1, "q": "美国强调“天才教育”的教育法案是（　）", "opts": ["《高等教育法》", "《职业教育法》", "《生计教育法》", "《国防教育法》"], "a": 3, "exp": "此题考查《国防教育法》。A.《高等教育法》关注高等教育发展。B.美国有职业教育性质的法案，但没有以“职业教育法”为名称的法案。C.《生计教育法》所倡导的生计教育以职业教育和劳动教育为核心。D.《国防教育法》强调“天才教育”，鼓励有才能的学生完成中等教育，攻读考入高等教育机构所必需的课程并升入该类机构，以培养拔尖人才。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 2, "q": "1958年，美国联邦政府颁布《国防教育法》，主张加强“新三艺”的教学。其中“新三艺”是指（　）", "opts": ["数学、自然科学、现代外语", "物理学、化学、数学", "人文科学、社会科学、自然科学", "哲学、经济学、政治学"], "a": 0, "exp": "此题考查《国防教育法》。1958年，美国联邦政府颁布《国防教育法》，该法令主要内容包括加强数学、自然科学、现代外语（“新三艺”）的教学。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 3, "q": "1958年，美国政府颁布了《国防教育法》，其核心目的是（　）", "opts": ["促进教育公平，缩小阶层差距", "建立国防教育体系，应对国际挑战", "提升教育质量，培养科技人才", "改革职业教育体系，提升学生的劳动技能"], "a": 2, "exp": "此题考查《国防教育法》。A.促进教育公平，缩小阶层差距是美国20世纪60年代教育改革的目的。B.《国防教育法》中的“国防”指国家科技竞争力，而非传统的军事国防教育。C.苏联发射人造卫星后，美国深感自身科技和教育竞争力落后，《国防教育法》应运而生。该法案的本质是通过提升教育质量，培养科技、工程等领域的专业人才，以应对科技挑战。√D.《国防教育法》中的职业教育是配合培养科技人才的辅助措施，该选项过度强化了法案对职业教育的影响。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 4, "q": "以下不属于20世纪60年代美国教育改革的主要方面的是（　）", "opts": ["中小学的课程改革", "整顿和规划师范教育", "继续解决教育机会不平等的问题", "发展高等教育，提高高等教育的质量"], "a": 1, "exp": "此题考查20世纪60年代美国的教育改革。20世纪60年代美国的教育改革主要在三个方面进行：一是中小学的课程改革；二是继续解决教育机会不平等的问题；三是发展高等教育，提高高等教育的质量。整顿和规划师范教育并非该时期改革的主要方面。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 5, "q": "20世纪70年代，由于美国公众对公立学校的教育质量普遍不满，美国掀起了（），实质上它是一种恢复传统教育的思潮。（　）", "opts": ["生计教育运动", "返回基础”教育运动", "初级学院运动", "赠地学院运动"], "a": 1, "exp": "此题考查生计教育。1971年，美国教育总署署长马兰为了提升学生的就业能力，倡导生计教育。生计教育的实质在于以职业教育和劳动教育为核心，引导和帮助人们在一生中学会许多新的知识和技能，以便在适应瞬息万变的社会的过程中，实现个人生存与社会发展的双重目的。生计教育针对的是普通教育学校，中小学是重点实施阶段。因此，答案选B。A.生计教育运动以职业教育和劳动教育为核心，生计教育实际上是一种扩大的职业教育。B.20世纪70年代，由于公众对公立学校的教育质量普遍不满，美国掀起了“返回基础”教育运动。“返回基础”教育运动实际上是美国的一种恢复传统教育的思潮，它否定了进步教育的一些基本主张，强调严格管理，有利于提高教育质量。√C.初级学院运动是一种从中等教育向高等教育过渡的教育。D.赠地学院运动开创了高等教育为工农业生产服务的方向。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 6, "q": "1983年，美国中小学教育质量调查委员会提出《国家处在危险之中：教育改革势在必行》的调查报告，这个报告是美国战后第三次教育改革的开端，但该运动引起了一些新的问题，其中不包括（　）", "opts": ["过分强调标准化的测试成绩，导致忽视学生个性的培养", "教学要求过于统一，导致缺乏灵活性", "过分强调提高教育标准和要求，使潜在的辍学人数迅速增加", "这场运动从实质上讲是一种恢复传统教育的思潮"], "a": 3, "exp": "此题考查《国家处在危险之中：教育改革势在必行》。D选项并非《国家处在危险之中：教育改革势在必行》导致的问题，且其表述属于“意义”的范畴。此", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 7, "q": "1983年，美国出台了《国家处在危险之中：教育改革势在必行》的调查报告，此报告中关于课程方面的改革是（.（　）", "opts": ["取消选修课，增加必修课，取消一切点缀性课程", "在义务教育阶段开设核心课程、基础课程和附加课程", "中学必须开设数学、英语、自然科学、社会科学、计算机课程", "把教学内容分为工具课程、启蒙性课程和体育课程三个部分"], "a": 2, "exp": "此题考查《国家处在危险之中：教育改革势在必行》。A.出自“返回基础”教育运动。B.出自《1988年教育改革法》。C.出自《国家处在危险之中：教育改革势在必行》。√D.出自《法国学校体制现代化建议》", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 8, "q": "20世纪50年代后，美国教育质量逐步提高，下列描述正确的一项是（　）", "opts": ["《国防教育法》主要是为了加强国防教育，保证教育安全", "20世纪60年代加强结构主义课程改革，用发现法促进学生的创造性发展，提高了教育质量", "20世纪70年代通过“返回基础”教育运动提升学生的阅读、写作和算术能力", "《国家处在危险之中：教育改革势在必行》突出活动课程的重要性"], "a": 2, "exp": "此题考查美国的教育改革。A.修改：《国防教育法》的命名只是为了突出教育的急迫性，内容是针对普通教育的。B.修改：20世纪60年代的结构主义课程改革过分强调知识本身，教与学均有难度，并没有提高教育质量。C.20世纪70年代的“返回基础”教育运动强调提升学生的阅读、写作和算术能力，逐步提高美国教育质量。√D.修改：《国家处在危险之中：教育改革势在必行》在课程结构中突出学术性课程的重要性，而不是活动课程。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 70}},
  {"id": "kc|edu-foreign|wj-10|知识点四|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 9, "q": "“正式把确立全国性中小学课程标准作为一项重要任务，要求每个州的教改计划都要包括课程内容标准的建立内容。”这一规定出自美国的（　）", "opts": ["《2000年目标：美国教育法》", "《美国2000年教育战略》", "《国防教育法》", "《国家处在危险之中：教育改革势在必行》"], "a": 0, "exp": "此题考查《2000年目标：美国教育法》。A.1994年，克林顿总统签署《2000年目标：美国教育法》，确立了国家和州级的内容标准、操作标准、学习机会标准以及州一级的评价标准。此法案正式把确立全国性中小学课程标准作为一项重要任务，要求每个州的教改计划都要包括课程内容标准的建立内容。√B.《美国2000年教育战略》在分析美国教育存在问题的基础上，明确指出未来美国教育改革的六大基C.1958年的《国防教育法》提出加强“新三艺”的教学和职业技术教育，强调“天才教育”，增拨大量教育经费。D.《国家处在危险之中：教育改革势在必行》以提高美国教育质量为中心，是20世纪80年代重要的纲领性文件。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-10|知识点四|10", "bank": "kc", "subj": "edu-foreign", "ch": "wj-10", "chName": "第十章 美国的近现代教育制度", "sec": "知识点四：20世纪下半叶的美国现代教育制度", "no": 10, "q": "在分析美国教育存在的问题的基础上，明确指出未来美国教育改革的六大基本目标的法案是（　）", "opts": ["《美国2000年教育战略》", "《2000年目标：美国教育法》", "《莫雷尔法案》", "《国家处在危险之中：教育改革势在必行》"], "a": 0, "exp": "此题考查《美国2000年教育战略》。A.《美国2000年教育战略》：1991年，美国签发《美国2000年教育战略》，在分析美国教育存在问题的基础上，明确指出未来美国教育改革的六大基本目标。√B.《2000年目标：美国教育法》：确立了国家和州级的内容标准、操作标准、学习机会标准以及州一级的评价标准。C.《莫雷尔法案》：核心是通过赠地建立农工学院，推动美国高等教育与工农业生产结合。D.《国家处在危险之中：教育改革势在必行》：以提高美国教育质量为中心。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-11|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 1, "q": "日本在明治维新时期颁布的教育法令是（　）", "opts": ["《教育基本法》", "《学校教育法》", "《学制令》", "《大学令》"], "a": 2, "exp": "此题考查明治维新时期的教育改革。A/B.《教育基本法》和《学校教育法》颁布于1947年，为战后日本教育指明了发展的方向。C.《学制令》颁布于1872年明治维新时期，是日本近代第一个教育改革法令，规定了日本的教育领导体制为中央集权式的大学区制。√D.《大学令》颁布于1918年，允许设立私立大学和地方公立大学。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-11|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 2, "q": "1872年，日本制定并颁布了近代第一个教育改革法令一—《学制令》。《学制令》对日本教育事业发展具有强制性的指导与规范作用，其中规定（　）", "opts": ["一律实行男女同校制度", "建立中央集权式的大学区制", "全体国民接受九年义务教育", "中学分为普通中学和职业中学"], "a": 1, "exp": "此题考查《学制令》。A.一律实行男女同校制度一《教育基本法》《学校教育法》B.建立中央集权式的大学区制—《学制令》。√C.全体国民接受九年义务教育一《教育基本法》。D.中学分为普通中学和职业中学一《学制令》的配套法令《中学校令》规定日本实行普通中学和实业中学，并不是职业中学。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-11|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 3, "q": "1886年，日本明治政府颁布的《中学校令》中，将普通中学分为（　）", "opts": ["职业中学和寻常中学", "私立中学和公立中学", "文科中学和实科中学", "寻常中学和高等中学"], "a": 3, "exp": "此题考查《中学校令》。1886年颁布的《中学校令》认为中学应当承担两大任务：实业教育和为学生升人高等学校做准备而实施的基础教育。其中，将普通中学分为寻常中学和高等中学。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-11|知识点一|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 4, "q": "日本明治维新的指导思想是“文明开化”，下列对其理解正确的一项是（　）", "opts": ["否定封建主义，主张资本主义", "全盘西化，完全放弃本民族的立场与文化", "不放弃本国文化，西方文化仅仅是辅助", "西方文化是主体，本国文化是辅助"], "a": 0, "exp": "此题考查明治维新时期的教育改革。A.“文明开化”的核心是破除封建等级制度与传统文化中阻碍近代化的因素，倡导学习西方的科学技术、教育制度、思想文化与生活方式，本质是为资本主义发展扫清障碍，主张发展资本主义。√B.修改：“文明开化”并非全盘西化，明治政府在后期也意识到过度西化的端，提出“和魂洋才”的理念，即保留日本传统文化的内核，吸纳西方先进技术与制度。C.修改：西方文化在明治维新中并不只是辅助，而是在科技、制度、教育等方面占主导地位，同时也保留本国文化，如道德、天皇制、部分习俗。D.修改：从社会改造、技术、制度等层面看，西方模式确实被当作主要学习对象，但政治上的主体仍是以天皇为中心的传统权力结构。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-11|知识点一|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 5, "q": "明治维新时期，日本教育改革中“和魂洋才”教育指导思想的核心内涵是（　）", "opts": ["完全抛弃日本传统文化，全面学习西方技术与制度", "以日本精神为根本，融合西方先进科技与文化知识", "优先传承儒家经典，排斥西方近代思想", "强调军事教育至上，培养对外扩张的人才"], "a": 1, "exp": "此题考查日本明治维新时期的教育改革。“和魂”指保留日本传统的民族精神，如忠君、武士道等，“洋才”指学习西方的科学技术、文化知识和近代制度，二者结合体现了明治政府在教育中平衡传统与近代化的意图。A选项“完全抛弃日本传统文化”不符合“和魂”，C选项“排斥西方近代思想”与“洋才”矛盾，D选项是后期军国主义教育的特点，并非“和魂洋才”的核心内涵。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 71}},
  {"id": "kc|edu-foreign|wj-11|知识点一|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 6, "q": "下列关于日本明治维新时期的教育，说法错误的是（　）", "opts": ["初等教育分为寻常小学和高等小学", "中等教育分为单科制高中和综合制高中", "新大学的创办以东京大学的成立为开端", "重视师范教育，师范学校实行公费制"], "a": 1, "exp": "此题考查日本明治维新时期的教育。日本于1886年颁布的《中学校令》规定，中学承担为学生升人高等学校做准备的基础教育和实业教育两大任务。日本的中学类型主要由普通中学（寻常中学和高等中学）和实业中学构成，除此之外还发展了女子中学。《学校教育法》规定，高中按课程设置情况分为单科制高中和综合制高中两类。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点一|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点一：19世纪的日本近代教育概况", "no": 7, "q": "在教育改革方面，日本明治维新与中国洋务运动的相同点不包括（　）", "opts": ["不希望丢掉本国的文化传统", "进行了全面而系统的改革", "聘请洋教员执教", "向海外派遣留学生"], "a": 1, "exp": "此题考查明治维新和洋务运动的异同点。日本明治维新对教育进行了全面而系统的改革，涉及各级各类的教育；洋务运动中的教育改革只是中国教育体系中的一小部分，主要集中于专门教育。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点二：20世纪上半叶的日本现代教育制度", "no": 1, "q": "1918年，日本政府颁布《大学令》。下列关于《大学令》的说法，正确的是（　）", "opts": ["除国立大学外，允许设立私立大学和地方公立大学", "大学教育以学术为中心，培养学生研究和实践的能力", "将原来多种类型的高等教育机构统一为单一类型的大学", "在大学基础上设立研究生院"], "a": 0, "exp": "此题考查《大学令》。B、C、D选项均为《学校教育法》的内容。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 1, "q": "“二战”后，确定日本教育体系实行分权制的法案是（　）", "opts": ["《教育基本法》", "《学校教育法》", "《教育敕语》", "《学校令》"], "a": 1, "exp": "此题考查《学校教育法》。A.1947年的《教育基本法》主要说明教育发展的宗旨和原则。B.1947年的《学校教育法》是《教育基本法》的具体化，规定了废除中央集权制，实行地方分权制。√C.《教育救语》于1890年颁布，加重了封建主义与军国主义的色彩。D.此为干扰选项。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 2, "q": "“确定教育必须以陶冶人格为目标，培养和平的国家及社会的建设者”的教育法案是（　）", "opts": ["《大学令》", "《学校教育法》", "《教育基本法》", "《教育救语》"], "a": 2, "exp": "此题考查《教育基本法》。A.《大学令》颁布于1918年，允许设立私立大学和地方公立大学。B.《学校教育法》是《教育基本法》的具体化。C.《教育基本法》强调教育必须以陶冶人格为目标，培养和平的国家及社会的建设者。√D.《教育救语》于1890年颁布，加重了封建主义与军国主义的色彩。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 3, "q": "《教育基本法》和《学校教育法》的关系是（　）", "opts": ["《教育基本法》是宗旨，《学校教育法》是具体措施", "《学校教育法》是宗旨，《教育基本法》是具体措施", "《教育基本法》和《学校教育法》是衔接的关系", "《教育基本法》以《学校教育法》为蓝本而编制"], "a": 0, "exp": "此题考查《教育基本法》和《学校教育法》的关系。3.：二者的关系为《教育基本法》是宗旨，《学校教育法》是具体措施。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 4, "q": "20世纪50年代日本的教育管理体制是（　）", "opts": ["中央集权制", "地方分权制", "中央、省、市三级管理体制", "中央与地方友好合作制"], "a": 1, "exp": "此题考查20世纪50年代日本的教育管理体制。日本从1947年颁布的《学校教育法》开始就废弃了中央集权制，实行地方分权制。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 5, "q": "下列选项中，不属于20世纪50一60年代日本教育改革特征的是（　）", "opts": ["制定振兴职业教育的政策，颁布《产业教育振兴法》", "将教育发展计划和教育政策编入国民经济计划，强调振兴科学技术", "出现应试教育占统治地位，人们抱怨学校是“考试地狱”等问题", "成立“临时教育审议会”，使之成为教育改革的领导机构"], "a": 3, "exp": "此题考查20世纪50一60年代日本教育改革的特征。1984年，日本国会批准成立“临时教育审议会”，使之成为20世纪80年代以来教育改革的领导机构之一。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 6, "q": "日本继明治维新和《教育基本法》两次重大改革之后的所谓“第三次教育改革”的主要依据是（　）", "opts": ["《关于面向21世纪的我国教育》", "《产业教育振兴法》", "《关于今后学校教育综合扩充、整顿的基本措施》", "《大学设置标准》"], "a": 2, "exp": "此题考查《关于今后学校教育综合扩充、整顿的基本措施》。A.《关于面向21世纪的我国教育》是20世纪90.年代日本中央教育审议会发表的报告，属于第三次教育改革的深化与延续，是改革中期的推进文件，并非最初的主要依据。B.《产业教育振兴法》是聚焦职业教育的专项法令。C.《关于今后学校教育综合扩充、整顿的基本措施》于1971年颁布，主要涉及中小学教育和高等教育方面的改革。该报告是日本继明治维新和《教育基本法》两次重大改革之后的所谓“第三次教育改革”的主要依据。√D.《大学设置标准》主要针对高等教育领域进行改革。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 72}},
  {"id": "kc|edu-foreign|wj-11|知识点三|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 7, "q": "20世纪80年代，日本国会批准成立的指导日本教育改革的领导机构是（　）", "opts": ["临时教育审议会", "中央教育审议会", "终身教育审议会", "地方教育审议会"], "a": 0, "exp": "此题考查“临时教育审议会”。1984年，日本成立了“临时教育审议会”，它成为推进日本20世纪80年代教育改革的领导机构之一。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点三|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 8, "q": "下列不属于“临时教育审议会”的贡献的是（　）", "opts": ["教育目的是培养青年一代具有广阔的胸怀、强健的体魄和丰富的创造力", "培养青年一代具有自由、自律的品格和公共精神，成为面向世界的日本人", "提出重视个性原则、国际化原则、信息化原则和向终身教育体制过渡原则", "完善职业教育体制，改革中小学教育体制"], "a": 3, "exp": "此题考查“临时教育审议会”。D选项表述错误，应改为完善终身教育体制，而不是职业教育体制。此题为选非题，因此，答案选D。（说明：考生有必要了解一下“临时教育审议会”的内容。）", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点三|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 9, "q": "进人20世纪90年代后，日本中央教育审议会提出《面向21世纪我国教育的发展方向》的咨询报告，这一报告指出未来日本教育改革的方向是（　）", "opts": ["国立大学法人化", "培养“具有主体性的日本人", "在宽松的环境中培养学生的生存能力", "综合学习时间"], "a": 2, "exp": "此题考查《面向21世纪我国教育的发展方向》。A.《21世纪的大学和今后的改革策略》《独立行政法人通则法》为“国立大学法人化”的重大改革奠定了基础。“国立大学法人化”改革启动于2004年。B.日本1998年的道德教育改革提出培养“具有主体性的日本人”。C.《面向21世纪我国教育的发展方向》指出日本教育改革的方向应是“在宽松的环境中培养学生的生存能力”。√D.《关于面向21世纪的我国教育》提出适应综合学习和课题学习的需要，设定“综合学习时间”。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点三|10", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 10, "q": "1991年，文部省对《大学设置标准》的修订，成为20世纪90年代日本高等教育改革的起点，并确立了该时期高等教育改革的主题内容。下列不属于此主题内容的是（　）", "opts": ["指出教育要在宽松的环境中培养学生的生存能力", "注重大学特色建设和个性发展，培养创造性人才", "改革研究生教育，提高科学研究的水平", "强化大学的社会服务意识，为民众提供终身学习的机会"], "a": 0, "exp": "此题考查《大学设置标准》。A选项为1996年日本中央教育审议会发表的《面向21世纪我国教育的发展方向》的主要思想，且是面向基础教育的，而B、C、D选项都是《大学设置标准》中面向高等教育的内容。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点三|11", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点三：20世纪下半叶的日本现代教育制度", "no": 11, "q": "20世纪90年代，日本主张国立大学从政府的下属机构转变为具有法人资格的独立机构。该措施的出处是（　）", "opts": ["《产业教育振兴法》", "《大学设置标准》", "《教育基本法》", "国立大学法人化”改革"], "a": 3, "exp": "此题考查20世纪90年代日本的教育改革。A.《产业教育振兴法》：20世纪50一60年代的教育改革，主要是为了振兴职业教育。B.《大学设置标准》：20世纪90年代的教育改革，突出了大学的育才、科研、为社会服务三项功能。C.《教育基本法》：20世纪40年代的教育改革，为“二战”后的日本教育指明了发展方向。D.“国立大学法人化”改革：20世纪90年代提出的教育改革，并于2004年启动，使国立大学从政府的下属机构转变为具有法人资格的独立机构。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点四：综合题", "no": 1, "q": "下列属于19世纪世界各国教育发展的共同特征的是（　）", "opts": ["国家化、世俗化、心理学化", "国家化、世俗化、终身化", "终身化、心理学化、义务化", "义务化、科学化、终身化"], "a": 0, "exp": "此题考查19世纪各国的教育发展特征。C、D选项。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点四|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点四：综合题", "no": 2, "q": "下列选项中，具有家庭教育属性的是（　）", "opts": ["古儒学校、骑士教育、绅士教育", "古儒学校、骑士教育、泛爱教育", "骑士教育、绅士教育、和谐教育", "骑士教育、绅士教育、城市教育"], "a": 0, "exp": "此题考查学校性质。古儒学校一—古代印度婆罗门教育，具有家庭教育性质。骑士教育一—中世纪一种特殊形式的家庭教育。绅士教育一17世纪中下半叶西欧社会贵族的家庭教育的主要模式。泛爱教育一18世纪70年代德国巴西多创办的新式学校教育。和谐教育一一古希腊自古以来的德、智、体、美等方面和谐发展的教育。城市教育一中世纪新兴市民阶层开办的初等新式学校教育。综上所述，古儒学校、骑士教育、绅士教育具有家庭教育属性。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点四|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点四：综合题", "no": 3, "q": "下列西欧各国的学校属于相同性质的一组是（　）", "opts": ["文法中学、实科中学、高级中学", "文科中学、古典中学、市立中学", "文法中学、现代中学、实科中学", "国立中学、实科中学、古典中学"], "a": 1, "exp": "此题考查西欧各国的中等学校。A、C、D选项中都有实科中学，因此首先从它人手分析。实科中学反对学习古典知识，主张学习实用性的自然科学知识，用现代语教学。文法中学是英国为贵族和大资产阶级子弟设立的，学习的是经典学科，与实科中学相反，排除A、C选项。古典中学主张学习古典知识，排除D选项。因此，答案选B。补充：（1）德国与俄国的文科中学相当于英国的文法学校和公学，具有强烈的古典主义色彩；（2）德国在《总纲计划》后设立高级中学，包括完全中学和学术中学；（3）国立中学和市立中学是法国19世纪主要的中等教育机构，主要教授古典语言与古典人文学科，古典主义色彩浓厚；（4）现代中学具有实科性质。（说明：欧洲国家的文科中学=文法中学=古典中学，实科中学=现代中学。）", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点四|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点四：综合题", "no": 4, "q": "下列教育改革事件或法案中没有试图衔接初等教育和中等教育的是（　）", "opts": ["统一学校运动", "《哈多报告》", "统一劳动学校", "初级学院运动"], "a": 3, "exp": "此题考查各个国家的教育改革。：“19世纪末至20世纪初兴起的初级学院运动有力地促进了美国高等教育的普及和发展，初级学院是一种从中等教育向高等教育过渡的教育。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点四|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点四：综合题", "no": 5, "q": "下列没有涉及职业教育改革的法案是（　）", "opts": ["美国的《史密斯一休斯法案》", "法国的《阿斯蒂埃法》", "英国的《巴尔福教育法》", "美国的《莫雷尔法案》"], "a": 2, "exp": "此题考查各国的职业教育法案。C选项的《巴尔福教育法》促成了中央与地方友好合作，形成了以地方为主的教育管理模式，不涉及职业教育改革。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-11|知识点四|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-11", "chName": "第十一章 日本的近现代教育制度", "sec": "知识点四：综合题", "no": 6, "q": "E套课程公众号【研大】拿破仑建立法兰西第一帝国后，设立帝国大学，实行学区管理，这一举措也对世界其他国家产生了影响。下列国家中未模仿该教育制度的是（　）", "opts": ["俄国", "中国", "日本", "美国"], "a": 3, "exp": "此题考查法国大学区制。A.俄国：19世纪受法国影响，建立了中央教育管理机构，划分学区统筹教育发展。B.中国：清末新政时期的教育改革，参考了包括法国在内的欧洲国家学制，设立学部作为中央教育行政机关，划分学区管理地方教育，带有明显的中央集权教育管理特征。C.日本：明治维新初期借鉴法国学区制，将全国划分为8个大学区，下设中学区、小学区。D.美国：教育管理实行地方分权制，教育权力主要归各州所有，联邦政府仅承担协调、资助等辅助职能，没有建立类似法国帝国大学的中央集权式教育管理体系，未模仿该制度。此题为选非题。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 73}},
  {"id": "kc|edu-foreign|wj-12|知识点一|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 1, "q": "（　）提出了“白板说”，认为人出生后心灵如同一块白板，一切知识都建立在经验的基础上。（　）", "opts": ["狄德罗", "康德", "洛克", "涂尔干"], "a": 2, "exp": "此题考查洛克的“白板说”。洛克同培根一样，反对流行的“天赋观念论”，提倡“白板说”，认为人出生后心灵如同一块白板，一切知识都建立在经验的基础上。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 2, "q": "洛克主张教育应该培养身体强健，举止优雅，有德行、智慧和实际才干的事业家。下列关于他的绅士教育的说法，不正确的是（　）", "opts": ["绅士教育是一种贵族教育", "绅士教育是一种学校教育", "绅士教育是一种家庭教育", "绅士教育是一种个人指导教育"], "a": 1, "exp": "此题考查洛克的绅士教育。绅士教育的本质就是培养既具有封建贵族遗风，又具有新兴资产阶级特点的新式人才。洛克反对学校教育，认为教育发挥其正面作用的场所并不在学校，因为学校集合了形形色色的儿童，教师不可能认真顾及每一个儿童。所以，为了顾及每个儿童天性的发展，找到适合儿童个性的个别指导，应该进行家庭教育。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 3, "q": "下列表述中，体现洛克绅士教育主张的是（　）", "opts": ["健康之精神寓于健康之身体", "身体健康重于精神健康", "精神健康重于身体健康", "健康之身体寓于健康之精神"], "a": 0, "exp": "此题考查洛克的绅士教育。洛克在《教育漫话》中提到了“健康之精神寓于健康之身体”，B、C、D选项都不是洛克对绅士教育的描述。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 4, "q": "洛克在《工作学校计划》中主张将贫民子弟组织起来教授宗教与技能，允许雇主挑选儿童当学徒。下列关于这一主张的说法，不正确的是（　）", "opts": ["具有民主性", "具有宗教性", "具有技能性", "具有职业性"], "a": 0, "exp": "此题考查洛克的贫民教育思想。洛克的贫民教育思想与他的绅士教育主张形成鲜明的对照，并没有体现民主性。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 5, "q": "）提出“科学知识最有价值”的卓越见解，并为每一种教育设计了课程，形成了以科学知识为核(心的课程体系。（　）", "opts": ["培根", "严复", "赫胥黎", "斯宾塞"], "a": 3, "exp": "此题考查斯宾塞的教育思想。斯宾塞提出“科学知识最有价值”，并且根据人类完满生活的需要，按照知识价值的顺序，为每一种教育设计了课程，形成了以科学知识为核心的课程体系。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 6, "q": "根据教育准备生活说和知识价值论，斯宾塞提出学校应该开设五种类型的课程。其中属于“间接保全自己的知识，是使文明生活得以维持的基础”课程的是（　）", "opts": ["生理学、解剖学", "逻辑学、力学、数学等", "历史学", "文学、艺术等"], "a": 1, "exp": "此题考查斯宾塞的教育思想。·A.生理学、解剖学是直接保全自己的知识。B.逻辑学、力学、数学等属于间接保全自己的知识。√C.历史学有利于调节人们的行为，成功履行公民的职责。D.文学、艺术等能够满足人们闲暇时休息与娱乐的需要。补充：除上述之外，还有生理学、心理学和教育学，这是履行父母责任必需的知识。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 7, "q": "斯宾塞认为“如果科学被抛弃，那么一切知识必然随之被抛弃”，并得出“科学知识最有价值”的结论，这是因为科学知识能（　）", "opts": ["传播宗教教义，维护社会稳定", "提升思辨能力，培育高尚品格", "服务未来生活，满足人生需求", "传承古典文化，培养绅士风范"], "a": 2, "exp": "此题考查斯宾塞的教育思想。A.斯宾塞的科学教育思想与宗教教义无关，他强调科学知识的实用性。B.斯宾塞更注重科学知识的实用性和对生活的意义，而非抽象的思辨或品格塑造。C.斯宾塞认为科学知识是应对生活各方面需求的基础，是“未来的完满生活”的保障。√D.斯宾塞反对英国古典主义知识，认为这类知识脱离实际生活，缺少价值。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 74}},
  {"id": "kc|edu-foreign|wj-12|知识点一|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点一：英国的近现代教育家", "no": 8, "q": "反对“单一重视科学教育而忽视古典人文学科教育”的教育家是（　）", "opts": ["赫胥黎", "培根", "斯宾塞", "巴西多"], "a": 0, "exp": "此题考查赫胥黎的教育思想。A.赫胥黎主张英国的各类学校必须实施科学教育，但他也批评当时的教育实践重视科学教育而忽视古典人文学科教育，他认为把二者结合起来才能算是完整的自由教育。√B.培根是科学教育的先驱，强调科学知识的价值。C.斯宾塞提出“科学知识最有价值”的著名论断，重视实用科学教育。D.巴西多倡导泛爱主义教育，注重实用知识。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点二|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点二：法国的近现代教育家", "no": 1, "q": "法国教育家（）提出了“教育万能论”。（　）", "opts": ["狄德罗", "涂尔干", "拉夏洛泰", "爱尔维修"], "a": 3, "exp": "此题考查爱尔维修的教育思想。爱尔维修把人的成长归因于教育与环境，但是他在这个问题上走向了极端，提出了“教育万能论”。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点二|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点二：法国的近现代教育家", "no": 2, "q": "法国启蒙思想家（）在《论国民教育》一书中系统地阐述了国家办学的教育思想。（　）", "opts": ["拉夏洛泰", "涂尔干", "爱尔维修", "卢梭"], "a": 0, "exp": "此题考查拉夏洛泰的著作。拉夏洛泰在《论国民教育》一书中系统地阐述了国家办学的教育思想。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点二|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点二：法国的近现代教育家", "no": 3, "q": "下列说法属于教育家拉夏洛泰的核心教育思想的是（　）", "opts": ["国民教育", "教育万能", "什么知识最有价值", "由“个体我”向“社会我”转变"], "a": 0, "exp": "此题考查拉夏洛泰的教育思想。A.拉夏洛泰系统地阐述了国家办学的教育思想。√B.爱尔维修提出“教育万能”的口号，否定遗传因素的影响。C.斯宾塞提出了“什么知识最有价值”的著名论断，认为“科学知识最有价值”。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点三|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点三：德国的近现代教育家", "no": 1, "q": "第斯多惠对德国教育尤其是师范教育的发展产生了举世公认的影响，被誉为“德国师范教育之父”，其教育理论代表作是（　）", "opts": ["《德国教师培养指南》", "《科学与教育》", "《人是教育的对象》", "《和教师的谈话》"], "a": 0, "exp": "此题考查第斯多惠的著作。A.《德国教师培养指南》是德国教育家第斯多惠的代表作。√B.《科学与教育》是英国著名自然科学家和教育家赫胥黎的代表作。C.《人是教育的对象》是俄国近现代教育家乌申斯基的代表作。D.《和教师的谈话》是苏联教育家赞科夫的代表作。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点三|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点三：德国的近现代教育家", "no": 2, "q": "第斯多惠认为教学中既要遵循文化原则，又要遵循自然原则，当二者发生冲突时，应首先遵循的原则是（　）", "opts": ["文化原则", "直观教学原则", "自然原则", "连续性与彻底性原则"], "a": 2, "exp": "此题考查第斯多惠的教学原则。第斯多惠认为教育者的一项重要任务是把遵循自然与遵循文化协调起来。当二者发生冲突时，遵循文化应该让位于遵循自然，遵循文化的教学原则仅次于遵循自然的教学原则。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点三|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点三：德国的近现代教育家", "no": 3, "q": "“教学的艺术不在于传授本领，而在于善于激励、唤醒和鼓舞。”这句名言出自（　）", "opts": ["康德", "洪堡", "第斯多惠", "费希特"], "a": 2, "exp": "此题考查第斯多惠的教育思想。该名言出自第斯多惠，他认为教育的作用在于激发主动性、促进自我完善。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点四|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点四：美国的近现代教育家", "no": 1, "q": "O以下不属于贺拉斯·曼的教育贡献的是（　）", "opts": ["开展公立学校运动", "师范教育的普及", "州教育领导体制的建立", "提出知识富人、教育立国的思想"], "a": 3, "exp": "此题考查贺拉斯·曼的教育思想。知识富人、教育立国是日本教育家福泽谕吉的思想。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点五|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点五：日本的近现代教育家", "no": 1, "q": "日本明治维新时期的著名教育家福泽谕吉，主张日本应实行以德、智、体为主的教育，他的教育代表作是（　）", "opts": ["《劝学篇》", "《学制令》", "《实业补习学校规程》", "《全人教育论》"], "a": 0, "exp": "此题考查福泽谕吉的著作。福泽谕吉是日本近代著名的启蒙思想家、教育家，其主要著作有《劝学篇》《文明论概略》等。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点六|1", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 1, "q": "被誉为“俄国教师的教师”的是（　）", "opts": ["马卡连柯", "赞科夫", "苏霍姆林斯基", "乌申斯基"], "a": 3, "exp": "此题考查乌申斯基的教育思想。乌申斯基是19世纪俄国著名的教育家，是俄国国民学校和教育科学的奠基人。他长期从事教育实践和教育理论研究工作，缔造了俄国女子师范教育，被誉为“俄国教师的教师”和“俄国教育科学的创始人”。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点六|2", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 2, "q": "乌申斯基认为教育的本质是（　）", "opts": ["教育是一门艺术，而不是一门科学汇套课程公众号【研大]", "教育是一门科学，而不是一门艺术", "教育既是一门科学，又是一门艺术", "教育既不是艺术，也不是科学"], "a": 0, "exp": "此题考查乌申斯基的教育思想。乌申斯基认为教育所关注的主要问题不应该是学校的教学科目、教学论或体育规则问题，而应该是人的精神和人生问题。所以说，教育是一门需要耐心、天赋的才能和本领以及专门知识的艺术。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 75}},
  {"id": "kc|edu-foreign|wj-12|知识点六|3", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 3, "q": "下列教育家中，认为“如果教育学希望从一切方面去教育人，那么就必须首先从一切方面去了解人”的是（　）", "opts": ["乌申斯基", "列宁", "马卡连柯", "赞科夫"], "a": 0, "exp": "此题考查乌申斯基的教育思想。A.乌申斯基：认为了解受教育者的身心发展规律是实施有效教育的前提，生理学和心理学是教育学的基础。题干内容体现了这一思想。√B.列宁：教育思想主要集中在教育与社会发展以及教育为社会主义建设服务等方面。C.马卡连柯：主要教育思想是集体教育、劳动教育和家庭教育。D.赞科夫：致力于发展性教学理论的研究，主要关注教学和发展的关系。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|4", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 4, "q": "苏联成立以后，率先指出社会主义教育必须同无产阶级的政治相联系，整个苏联的教育事业必须贯彻无产阶级精神和注重共产主义道德的培养，为无产阶级专政服务，最终实现共产主义的教育家是（　）", "opts": ["赞科夫", "巴班斯基", "列宁", "苏霍姆林斯基"], "a": 2, "exp": "此题考查列宁的教育思想。列宁是19世纪末20世纪初苏联著名的无产阶级革命家、政治家、教育家。他十分关注教育事业的发展，始终将教育看作无产阶级革命和社会主义建设的重要组成部分，他的教育思想对苏联的教育改革和发展起着重要的指导作用。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|5", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 5, "q": "苏联第一位马克思主义教育家，苏联著名的社会主义教育理论家和组织者，苏维埃教育学的奠基人之一是（　）", "opts": ["克鲁普斯卡娅", "巴班斯基", "列宁", "苏霍姆林斯基"], "a": 0, "exp": "此题考查克鲁普斯卡娅的教育思想。克鲁普斯卡娅是苏联第一位马克思主义教育家，苏联著名的社会主义教育理论家和组织者，苏维埃教育学的奠基人之一。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|6", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 6, "q": "下列关于马卡连柯的教育理论的表述，不正确的是（　）", "opts": ["集体教育应与劳动教育相结合", "优良的家庭教育助力于集体教育", "纪律是达到集体目的的最好方式", "教育既与个人发生关系，又与集体发生关系"], "a": 3, "exp": "此题考查马卡连柯的教育思想。马卡连柯认为，正确教育的方式应该设法不与个人发生关系，而只与集体发生关系，使每个学生都不得不参加共同的活动。他把这种教育形式称为“平行教育”。此题为选非题，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|7", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 7, "q": "赞科夫是20世纪60—70年代苏联最有影响力的教育家，他的《教学与发展》一书着重体现了他长期领导的（）的教育实验。（　）", "opts": ["教学与发展", "直观教学与智育", "形式教学与实质教学", "最近发展区"], "a": 0, "exp": "A记忆题此题考查赞科夫的“教学与发展的实验”。赞科夫是20世纪60一70年代苏联最有影响力的教育家，代表作是《教学与发展》《和教师的谈话》，他通过教学与发展的教育实验提出他的发展性教学理论。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|8", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 8, "q": "下列关于赞科夫提出的“一般发展”的概念，表述错误的是（　）", "opts": ["一般发展”就是“全面发展", "一般发展”不同于“特殊发展", "一般发展”反对“片面发展", "一般发展”包括“智力发展"], "a": 0, "exp": "此题考查赞科夫的教育思想。赞科夫提出的“一般发展”的概念针对的是人的生理与心理的发展，被理解为个性的发展。“全面发展”是社会教育学方面的概念，二者不能等同。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|9", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 9, "q": "以下赞科夫的教学原则中，在实验教学体系中起决定性作用的是（　）", "opts": ["以高难度进行教学的原则", "以高速度进行教学的原则", "使学生理解学习过程的原则", "理论知识起主导作用的原则"], "a": 0, "exp": "此题考查赞科夫的教学原则。赞科夫认为，以高难度进行教学的原则在实验教学体系中起决定性的作用。高难度并不意味着越难越好，难度要控制在学生的“最近发展区”范围内。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|10", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 10, "q": "赞科夫提出的发展性教学理论的教学原则中，高难度教学原则占据着重要地位。下列对高难度教学原则的理解，正确的是（　）", "opts": ["①②", "②③", "②④", "③④"], "a": 2, "exp": "此题考查赞科夫的高难度教学原则。赞科夫的高速度教学原则并不是指教学速度越快越好，而是指要以适当的速度进行教学，排除①。赞科夫的高难度教学原则指出，适当提高教学难度，可以调动学生的求知欲，同时，针对传统教材过于简单的问题，需要提高难度，但要符合学生的身心发展水平，将难度控制在学生的“最近发展区”范围内，", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|11", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 11, "q": "）提出“教学教育过程最优化的理论，是教育学发展中合乎逻辑的一个阶段。它直接以教育学先（前所取得的成就作为依据”。（　）", "opts": ["夸美纽斯", "赫尔巴特", "巴班斯基", "卢梭"], "a": 2, "exp": "此题考查巴班斯基的教育思想。巴班斯基是苏联著名的教育家、教学论专家。20世纪70年代，为了克服学生普遍存在的留级、学习成绩不佳的现象，他提出要对学校教学进行整体优化，提出了教学教育过程最优化理论。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 76}},
  {"id": "kc|edu-foreign|wj-12|知识点六|12", "bank": "kc", "subj": "edu-foreign", "ch": "wj-12", "chName": "第十二章 近现代主要的教育家", "sec": "知识点六：俄国（苏联）的近现代教育家", "no": 12, "q": "下列关于苏霍姆林斯基的思想，表述错误的是（　）", "opts": ["主张个性全面和谐发展的教育", "劳动教育是和谐发展的核心", "重视学生的精神生活", "强调要相信学生"], "a": 1, "exp": "此题考查苏霍姆林斯基的教育思想。苏霍姆林斯基重视劳动教育在个性全面和谐发展中的作用，但未把劳动教育视为和谐发展的核心。他认为个性全面和谐发展的核心是高尚的道德。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 77}}
]);
